using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CourseService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CourseService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events, civilizations, and cultures." },
            new() { Id = 6, Name = "Biology", Code = "BIO", Description = "Study of living organisms and life processes." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers in top-tier conferences and holds two patents in natural language processing.", Email = "achen@university.edu", OfficeLocation = "Science Building 301" },
            new() { Id = 2, Name = "Dr. Robert Martinez", Title = "Associate Professor of Computer Science", Bio = "Dr. Martinez focuses on software engineering and distributed systems. Before joining academia, he spent 10 years at a leading tech company building large-scale infrastructure.", Email = "rmartinez@university.edu", OfficeLocation = "Science Building 305" },
            new() { Id = 3, Name = "Dr. Sarah Johnson", Title = "Professor of Mathematics", Bio = "Dr. Johnson is an expert in abstract algebra and number theory. She is the recipient of the National Mathematics Award and has mentored over 20 PhD students.", Email = "sjohnson@university.edu", OfficeLocation = "Math Hall 210" },
            new() { Id = 4, Name = "Dr. James Lee", Title = "Associate Professor of Physics", Bio = "Dr. Lee researches quantum mechanics and particle physics. He has contributed to experiments at CERN and frequently presents at international physics symposiums.", Email = "jlee@university.edu", OfficeLocation = "Physics Lab 104" },
            new() { Id = 5, Name = "Prof. Emily Carter", Title = "Professor of English", Bio = "Prof. Carter is a published author and literary critic specializing in contemporary American fiction. She brings real-world writing experience to the classroom.", Email = "ecarter@university.edu", OfficeLocation = "Humanities 402" },
            new() { Id = 6, Name = "Dr. Michael Brown", Title = "Associate Professor of History", Bio = "Dr. Brown studies early modern European history and the history of science. He has authored three books on the Scientific Revolution.", Email = "mbrown@university.edu", OfficeLocation = "Humanities 310" },
            new() { Id = 7, Name = "Dr. Lisa Nguyen", Title = "Professor of Biology", Bio = "Dr. Nguyen is a molecular biologist who studies gene expression in plant systems. Her lab has received continuous NIH funding for the past decade.", Email = "lnguyen@university.edu", OfficeLocation = "Life Sciences 205" }
        };

        var cs = _departments[0];
        var math = _departments[1];
        var phys = _departments[2];
        var eng = _departments[3];
        var hist = _departments[4];
        var bio = _departments[5];

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to the field of computer science covering fundamental concepts such as algorithms, data structures, programming paradigms, and computational thinking. No prior programming experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Building 101", DepartmentId = 1, Department = cs, Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms). Includes analysis of time and space complexity.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Location = "Science Building 201", DepartmentId = 1, Department = cs, Instructor = _instructors[0] },
            new() { Id = 3, Code = "CS 310", Title = "Software Engineering", Description = "Principles and practices of software development including requirements analysis, system design, testing methodologies, version control, and agile project management. Includes a team-based capstone project.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Science Building 305", DepartmentId = 1, Department = cs, Instructor = _instructors[1], IsFeatured = true },
            new() { Id = 4, Code = "CS 450", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search, knowledge representation, machine learning, neural networks, and natural language processing. Students implement AI agents in Python.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Science Building 301", DepartmentId = 1, Department = cs, Instructor = _instructors[0] },
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and the natural sciences. Emphasis on both conceptual understanding and problem-solving skills.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Hall 101", DepartmentId = 2, Department = math, Instructor = _instructors[2], IsFeatured = true },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Systems of linear equations, matrices, vector spaces, linear transformations, eigenvalues, and eigenvectors. Foundational for advanced work in mathematics, computer science, and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Math Hall 201", DepartmentId = 2, Department = math, Instructor = _instructors[2] },
            new() { Id = 7, Code = "MATH 301", Title = "Abstract Algebra", Description = "Groups, rings, and fields. Homomorphisms, isomorphisms, and quotient structures. Applications to coding theory and cryptography.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Math Hall 210", DepartmentId = 2, Department = math, Instructor = _instructors[2] },
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Covers Newton's laws, conservation of energy and momentum, rotational dynamics, and oscillations. Lab component included.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Physics Lab 101", DepartmentId = 3, Department = phys, Instructor = _instructors[3] },
            new() { Id = 9, Code = "PHYS 201", Title = "Modern Physics", Description = "Special relativity, quantum mechanics, atomic structure, and nuclear physics. Introduction to the concepts that revolutionized our understanding of the physical universe.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Location = "Physics Lab 104", DepartmentId = 3, Department = phys, Instructor = _instructors[3], IsFeatured = true },
            new() { Id = 10, Code = "ENG 101", Title = "College Composition", Description = "Development of writing skills through analysis and composition. Focus on critical reading, argumentation, and clear, effective prose. Students write multiple essays with peer review.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", Location = "Humanities 201", DepartmentId = 4, Department = eng, Instructor = _instructors[4] },
            new() { Id = 11, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present. Examines major movements including Transcendentalism, Realism, Modernism, and Postmodernism.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Humanities 402", DepartmentId = 4, Department = eng, Instructor = _instructors[4] },
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations and events from prehistory through the late medieval period. Covers the development of agriculture, early empires, classical civilizations, and the spread of world religions.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Humanities 310", DepartmentId = 5, Department = hist, Instructor = _instructors[5] },
            new() { Id = 13, Code = "HIST 220", Title = "The Scientific Revolution", Description = "Explores the transformation of natural philosophy in early modern Europe, from Copernicus through Newton. Examines the social, political, and religious contexts of scientific change.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Location = "Humanities 310", DepartmentId = 5, Department = hist, Instructor = _instructors[5], IsFeatured = true },
            new() { Id = 14, Code = "BIO 101", Title = "Introduction to Biology", Description = "Foundational biology covering cell structure, genetics, evolution, ecology, and organismal diversity. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM", Location = "Life Sciences 101", DepartmentId = 6, Department = bio, Instructor = _instructors[6] },
            new() { Id = 15, Code = "BIO 310", Title = "Molecular Biology", Description = "Structure and function of biological macromolecules, DNA replication, transcription, translation, and gene regulation. Modern techniques including PCR, gel electrophoresis, and CRISPR.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM", Location = "Life Sciences 205", DepartmentId = 6, Department = bio, Instructor = _instructors[6] }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database.
        return request.CourseId > 0
            && !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId);
    }
}

