@using CourseCatalog.Models

<div class="card h-100 shadow-sm">
    <div class="card-body">
        <span class="badge bg-secondary mb-2">@Course.Code</span>
        <span class="badge bg-info mb-2">@Course.Credits Credits</span>
        <h5 class="card-title">@Course.Title</h5>
        <p class="card-text text-muted small">@Course.Department.Name &bull; @Course.Instructor.Name</p>
        <p class="card-text">@Truncate(Course.Description, 120)</p>
    </div>
    <div class="card-footer bg-transparent border-top-0">
        <a href="courses/@Course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Course Course { get; set; } = null!;

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

@using CourseCatalog.Models

<div class="card">
    <div class="card-body">
        <h5 class="card-title">@Instructor.Name</h5>
        <h6 class="card-subtitle mb-2 text-muted">@Instructor.Title</h6>
        <p class="card-text">@Instructor.Bio</p>
        <ul class="list-unstyled mb-0">
            <li><strong>Email:</strong> <a href="mailto:@Instructor.Email">@Instructor.Email</a></li>
            <li><strong>Office:</strong> @Instructor.OfficeLocation</li>
        </ul>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Instructor Instructor { get; set; } = null!;
}

@using CourseCatalog.Models

<div class="row row-cols-1 row-cols-md-3 g-4">
    @foreach (var course in Courses)
    {
        <div class="col">
            <CourseCard Course="course" />
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<Course> Courses { get; set; } = new();
}

@using CourseCatalog.Models

<div class="row row-cols-2 row-cols-md-3 row-cols-lg-6 g-3">
    @foreach (var dept in Departments)
    {
        <div class="col">
            <a href="courses?departmentId=@dept.Id" class="text-decoration-none">
                <div class="card text-center h-100 border-primary">
                    <div class="card-body">
                        <h6 class="card-title mb-1">@dept.Code</h6>
                        <p class="card-text small text-muted mb-0">@dept.Name</p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<Department> Departments { get; set; } = new();
}

@using CourseCatalog.Models

<div class="row g-3 mb-4">
    <div class="col-md-8">
        <input type="text"
               class="form-control"
               placeholder="Search by title, code, description, or instructor…"
               value="@SearchTerm"
               @oninput="OnSearchInput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" value="@DepartmentId" @onchange="OnDepartmentChange">
            <option value="0">All Departments</option>
            @foreach (var dept in Departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
</div>

@code {
    [Parameter] public string? SearchTerm { get; set; }
    [Parameter] public int DepartmentId { get; set; }
    [Parameter] public EventCallback<string?> SearchTermChanged { get; set; }
    [Parameter] public EventCallback<int> DepartmentIdChanged { get; set; }

    [Parameter, EditorRequired]
    public List<Department> Departments { get; set; } = new();

    private async Task OnSearchInput(ChangeEventArgs e)
    {
        SearchTerm = e.Value?.ToString();
        await SearchTermChanged.InvokeAsync(SearchTerm);
    }

    private async Task OnDepartmentChange(ChangeEventArgs e)
    {
        DepartmentId = int.TryParse(e.Value?.ToString(), out var id) ? id : 0;
        await DepartmentIdChanged.InvokeAsync(DepartmentId);
    }
}

