@code {
    [Parameter] public string? SearchTerm { get; set; }
    [Parameter] public int DepartmentId { get; set; }
    [Parameter] public EventCallback<string?> SearchTermChanged { get; set; }
    [Parameter] public EventCallback<int> DepartmentIdChanged { get; set; }

    [Parameter, EditorRequired]
    public List<Department> Departments { get; set; } = new();

    private async Task OnSearchInput(ChangeEventArgs e)
    {
        SearchTerm = e.Value?.ToString();
        await SearchTermChanged.InvokeAsync(SearchTerm);
    }

    private async Task OnDepartmentChange(ChangeEventArgs e)
    {
        DepartmentId = int.TryParse(e.Value?.ToString(), out var id) ? id : 0;
        await DepartmentIdChanged.InvokeAsync(DepartmentId);
    }
}

