@page "/"
@using CourseCatalog.Services
@using CourseCatalog.Components.Shared
@inject CourseService CourseService

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-5 fw-bold">University Course Catalog</h1>
    <p class="lead text-muted">Explore departments, browse courses, and submit your enrollment request.</p>
    <a href="courses" class="btn btn-primary btn-lg me-2">Browse All Courses</a>
    <a href="enroll" class="btn btn-outline-secondary btn-lg">Enroll Now</a>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    <FeaturedCourses Courses="featuredCourses" />
</section>

<section class="mb-5">
    <h2 class="mb-3">Departments</h2>
    <DepartmentLinks Departments="departments" />
</section>

@code {
    private List<Models.Course> featuredCourses = new();
    private List<Models.Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = CourseService.GetFeaturedCourses();
        departments = CourseService.GetDepartments();
    }
}

@page "/courses"
@rendermode InteractiveServer
@using CourseCatalog.Services
@using CourseCatalog.Components.Shared
@inject CourseService CourseService

<PageTitle>Browse Courses – University Course Catalog</PageTitle>

<h1 class="mb-4">Browse Courses</h1>

<CourseFilters SearchTerm="@searchTerm"
              SearchTermChanged="OnSearchChanged"
              DepartmentId="@departmentId"
              DepartmentIdChanged="OnDepartmentChanged"
              Departments="departments" />

<p class="text-muted mb-3">Showing @filteredCourses.Count course(s)</p>

<CourseList Courses="filteredCourses" />

@code {
    [SupplyParameterFromQuery]
    public int? DepartmentIdQuery { get; set; }

    private string? searchTerm;
    private int departmentId;
    private List<Models.Department> departments = new();
    private List<Models.Course> filteredCourses = new();

    protected override void OnInitialized()
    {
        departments = CourseService.GetDepartments();
        departmentId = DepartmentIdQuery ?? 0;
        ApplyFilters();
    }

    private void OnSearchChanged(string? term)
    {
        searchTerm = term;
        ApplyFilters();
    }

    private void OnDepartmentChanged(int deptId)
    {
        departmentId = deptId;
        ApplyFilters();
    }

    private void ApplyFilters()
    {
        filteredCourses = CourseService.SearchCourses(searchTerm, departmentId);
    }
}

@page "/courses/{Id:int}"
@using CourseCatalog.Models
@using CourseCatalog.Services
@using CourseCatalog.Components.Shared
@inject CourseService CourseService

<PageTitle>@(course?.Title ?? "Course Not Found") – University Course Catalog</PageTitle>

@if (course is null)
{
    <div class="alert alert-warning">
        <h4>Course Not Found</h4>
        <p>The course you're looking for doesn't exist. <a href="courses">Browse all courses</a>.</p>
    </div>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item"><a href="courses?departmentId=@course.DepartmentId">@course.Department.Name</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@course.Title</h1>
            <p class="lead text-muted">@course.Code &bull; @course.Department.Name</p>
            <p>@course.Description</p>

            <table class="table table-bordered w-auto">
                <tbody>
                    <tr><th>Credits</th><td>@course.Credits</td></tr>
                    <tr><th>Schedule</th><td>@course.Schedule</td></tr>
                    <tr><th>Location</th><td>@course.Location</td></tr>
                </tbody>
            </table>

            <a href="enroll?courseId=@course.Id" class="btn btn-primary">Enroll in This Course</a>
        </div>

        <div class="col-lg-4">
            <h4 class="mb-3">Instructor</h4>
            <InstructorBio Instructor="course.Instructor" />
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;

    protected override void OnInitialized()
    {
        course = CourseService.GetCourse(Id);
    }
}

@page "/enroll"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CourseService CourseService

<PageTitle>Enrollment Request – University Course Catalog</PageTitle>

<h1 class="mb-4">Submit Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request for <strong>@selectedCourseName</strong> has been received. You will receive a confirmation via your university email.</p>
        <hr>
        <a href="courses" class="btn btn-outline-success">Browse More Courses</a>
        <a href="enroll" class="btn btn-outline-primary ms-2">Submit Another</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment" method="post">
                <AntiforgeryToken />
                <DataAnnotationsValidator />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="model.StudentName" />
                    <ValidationMessage For="() => model.StudentName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="model.StudentId" placeholder="e.g., CS123456" />
                    <ValidationMessage For="() => model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="model.CourseId">
                        <option value="0">-- Select a course --</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id">@course.Code – @course.Title</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.CourseId" />
                </div>

                <div class="mb-3">
                    <label for="notes" class="form-label">Additional Notes (optional)</label>
                    <InputTextArea id="notes" class="form-control" rows="3" @bind-Value="model.Notes" />
                    <ValidationMessage For="() => model.Notes" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            </EditForm>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<Course> courses = new();
    private bool submitted;
    private string selectedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        courses = CourseService.GetAllCourses();

        if (CourseId.HasValue && model.CourseId == 0)
        {
            model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = CourseService.GetCourse(model.CourseId);
        selectedCourseName = course is not null ? $"{course.Code} – {course.Title}" : "Unknown Course";

        if (CourseService.SubmitEnrollmentRequest(model))
        {
            submitted = true;
        }
    }
}

